{
  "name": "veditbox",
  "version": "1.1.0",
  "description": "Utility Box to paste url, image data or record audio then drag it out as an file to another application.",
  "main": "src/main/index.js",
  "scripts": {
    "postinstall": "electron-builder install-app-deps",
    "start": "electron .",
    "build": "electron-builder --dir",
    "dist": "electron-builder"
  },
  "author": "Mayk Brito <maykbrito@gmail.com>",
  "license": "MIT",
  "devDependencies": {
    "electron": "^33",
    "electron-builder": "25.1.8"
  },
  "dependencies": {
    "@electron/remote": "^2.1.2",
    "@ffmpeg-installer/ffmpeg": "^1.1.0",
    "fluent-ffmpeg": "^2.1.3",
    "imagemagick": "^0.1.3",
    "lucide": "^0.454.0",
    "yt-dlp-wrap": "^2.3.12"
  },
  "build": {
    "appId": "mb.veditbox",
    "asar": false,
    "mac": {
      "category": "public.app-category.utilities"
    },
    "files": [
      "src/**/*",
      "build",
      "node_modules/**/*"
    ]
  }
}

{
  "name": "giphy-action",
  "version": "0.0.0",
  "scripts": {
    "dev": "convex dev --start 'vite --open'",
    "build": "tsc --noEmit && vite build"
  },
  "dependencies": {
    "convex": "1.42.1",
    "react": "^18.0.0",
    "react-dom": "^18.0.0",
    "prettier": "3.8.1"
  },
  "devDependencies": {
    "@types/babel__core": "^7.20.0",
    "@types/node": "^18.17.0",
    "@types/react": "^18.0.0",
    "@types/react-dom": "^18.0.0",
    "@vitejs/plugin-react": "^4.2.1",
    "typescript": "~5.0.3",
    "vite": "^6.4.3"
  }
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
});

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  /* config options here */
};

export default nextConfig;

import mdx from '@astrojs/mdx'
import react from '@astrojs/react'
import sitemap from '@astrojs/sitemap'
import svelte from '@astrojs/svelte'
import tailwind from '@astrojs/tailwind'
import { defineConfig } from 'astro/config'

// https://astro.build/config
export default defineConfig({
  site: 'https://maykbrito.dev',
  integrations: [
    react(),
    tailwind({
      applyBaseStyles: false,
    }),
    sitemap(),
    mdx(),
    svelte(),
  ],
  output: 'static',
})

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  /* config options here */
};

export default nextConfig;

