    "electron-store": "^8.2.0",
    "json-schema-typed": "^8.0.1"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/maykbrito/simple-webview.git"
  },
  "keywords": [
    "browser",
    "webview",
    "minimalism"
  ],
  "author": "Mayk Brito",
  "license": "MIT",
  "homepage": "https://github.com/maykbrito/simple-webview#readme"
}
